?>
<section <?php echo nextsaas_section_attrs( 'home-team-solutions', $attributes, array( 'section' ) ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?>><div class="container"><div class="section-heading"><p class="eyebrow" data-nextsaas-rich="eyebrow"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'eyebrow' ) ); ?></p><div class="heading-row"><h2 data-nextsaas-rich="heading"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'heading' ) ); ?></h2><p class="lead" data-nextsaas-rich="lead"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'lead' ) ); ?></p></div></div><div class="product-tabs" role="tablist" aria-label="<?php echo esc_attr( nextsaas_attr( $attributes, 'tablistLabel' ) ); ?>"><?php foreach ( $nextsaas_panels as $nextsaas_i => $nextsaas_panel ) : ?><button id="tab-<?php echo esc_attr( (string) ( $nextsaas_panel['key'] ?? $nextsaas_i ) ); ?>" type="button" role="tab" aria-selected="<?php echo 0 === $nextsaas_i ? 'true' : 'false'; ?>" aria-controls="team-panel-<?php echo esc_attr( (string) $nextsaas_i ); ?>"<?php echo 0 === $nextsaas_i ? '' : ' tabindex="-1"'; ?> data-team="<?php echo esc_attr( (string) ( $nextsaas_panel['key'] ?? '' ) ); ?>" data-nextsaas-rich="panels.<?php echo esc_attr( (string) $nextsaas_i ); ?>.tab"><?php echo nextsaas_rich( (string) ( $nextsaas_panel['tab'] ?? '' ) ); ?></button><?php endforeach; ?></div><?php foreach ( $nextsaas_panels as $nextsaas_i => $nextsaas_panel ) : ?><div class="team-panel" id="team-panel-<?php echo esc_attr( (string) $nextsaas_i ); ?>" role="tabpanel" aria-labelledby="tab-<?php echo esc_attr( (string) ( $nextsaas_panel['key'] ?? $nextsaas_i ) ); ?>"<?php echo 0 === $nextsaas_i ? '' : ' hidden'; ?>><div><span class="meta" data-nextsaas-rich="panels.<?php echo esc_attr( (string) $nextsaas_i ); ?>.meta"><?php echo nextsaas_rich( (string) ( $nextsaas_panel['meta'] ?? '' ) ); ?></span><h3 data-nextsaas-rich="panels.<?php echo esc_attr( (string) $nextsaas_i ); ?>.heading"><?php echo nextsaas_rich( (string) ( $nextsaas_panel['heading'] ?? '' ) ); ?></h3><p data-nextsaas-rich="panels.<?php echo esc_attr( (string) $nextsaas_i ); ?>.body"><?php echo nextsaas_rich( (string) ( $nextsaas_panel['body'] ?? '' ) ); ?></p><a class="text-link" href="<?php echo esc_url( nextsaas_attr( $attributes, 'ctaUrl' ) ); ?>" data-nextsaas-rich="ctaLabel"><?php echo nextsaas_rich( nextsaas_attr( $attributes, 'ctaLabel' ) ); ?> <span><?php echo nextsaas_icon( 'arrow-up-right' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></span></a></div><?php echo nextsaas_media( $nextsaas_media, 'ph-img image-reserve' ); // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped?></div><?php endforeach; ?></div></section>
